#include <cstdint>

std::uint32_t pack(std::uint32_t r, std::uint32_t g, std::uint32_t b)
{
    return (r << 16) | (g << 8) | b;
}

std::uint32_t redOf(std::uint32_t colour)
{
    return (colour >> 16) & 0xFF;
}

std::uint32_t greenOf(std::uint32_t colour)
{
    return (colour >> 8) & 0xFF;
}

std::uint32_t blueOf(std::uint32_t colour)
{
    return colour & 0xFF;
}

unitTests:
TEST("pack orange") { CHECK_EQ(pack(0xFF, 0x88, 0x00), 0xFF8800u); }
TEST("pack black and white") { CHECK_EQ(pack(0, 0, 0), 0u); CHECK_EQ(pack(255, 255, 255), 0xFFFFFFu); }
TEST("unpack each channel") { CHECK_EQ(redOf(0x12ABEFu), 0x12u); CHECK_EQ(greenOf(0x12ABEFu), 0xABu); CHECK_EQ(blueOf(0x12ABEFu), 0xEFu); }
TEST("round trip") { const auto c{ pack(10, 200, 37) }; CHECK_EQ(redOf(c), 10u); CHECK_EQ(greenOf(c), 200u); CHECK_EQ(blueOf(c), 37u); }

